BLUE='#163B55';TEAL='#087F8C';ORANGE='#B66322'
def num(x,n=2):return 'pendiente' if x is None else f'{x:,.{n}f}'
def doc_outputs(blocks,path,title):
    path.parent.mkdir(parents=True,exist_ok=True)
    font=Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf');bold=font.with_name('DejaVuSans-Bold.ttf')
    if 'DV' not in pdfmetrics.getRegisteredFontNames():pdfmetrics.registerFont(TTFont('DV',str(font)));pdfmetrics.registerFont(TTFont('DVB',str(bold)))
    ss=getSampleStyleSheet();ss.add(ParagraphStyle('BodyLP',fontName='DV',fontSize=9.2,leading=14,spaceAfter=7,alignment=TA_JUSTIFY,textColor=colors.HexColor('#243746')))
    ss.add(ParagraphStyle('HLP',fontName='DVB',fontSize=15,leading=20,textColor=colors.HexColor(BLUE),spaceBefore=12,spaceAfter=10))
    ss.add(ParagraphStyle('SubLP',fontName='DVB',fontSize=11,leading=16,textColor=colors.HexColor(TEAL),spaceBefore=9,spaceAfter=6))
    ss.add(ParagraphStyle('CellLP',fontName='DV',fontSize=7.2,leading=10))
    story=[];word=Document();sec=word.sections[0];sec.top_margin=Cm(2.1);sec.bottom_margin=Cm(2.);sec.left_margin=sec.right_margin=Cm(1.8)
    normal=word.styles['Normal'];normal.font.name='DejaVu Sans';normal.font.size=Pt(10)
    word.add_heading(title,0);word.add_paragraph('Limbani–Huancasayani | Instalaciones Eléctricas II | LP-R02 | 18/10/2026')
    story.extend([Paragraph(html.escape(title),ss['HLP']),Paragraph('Limbani–Huancasayani · Instalaciones Eléctricas II<br/>LP-R02 · 18 de octubre de 2026',ss['BodyLP']),Spacer(1,4*mm)])
    md=['# '+title,'','LP-R02 · 18/10/2026 · Diseño académico revisable','']
    for b in blocks:
        typ=b[0]
        if typ in ['h','sub']:
            s=humano(b[1]);story.append(Paragraph(html.escape(s),ss['HLP' if typ=='h' else 'SubLP']));word.add_heading(s,1 if typ=='h' else 2);md+=['#'*(2 if typ=='h' else 3)+' '+s,'']
        elif typ=='p':
            s=humano(b[1]);story.append(Paragraph(html.escape(s).replace('\n','<br/>'),ss['BodyLP']));word.add_paragraph(s);md +=[s,'']
        elif typ=='table':
            headers,rows=b[1:];headers=[humano(x) for x in headers];rows=[[humano(x) for x in row] for row in rows];data=[[Paragraph(html.escape(str(v)),ss['CellLP']) for v in row] for row in [headers]+rows]
            width=174*mm;weights=b[3] if len(b)>3 else [1]*len(headers)
            tab=Table(data,colWidths=[width*w/sum(weights) for w in weights],repeatRows=1,hAlign='LEFT')
            tab.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#DFECF1')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F6F8')]),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor(TEAL)),('LINEBELOW',(0,-1),(-1,-1),.3,colors.HexColor('#CBD5DB'))]))
            story.extend([tab,Spacer(1,3*mm)])
            t=word.add_table(rows=1,cols=len(headers));t.style='Light Shading Accent 1'
            for cell,v in zip(t.rows[0].cells,headers):cell.text=str(v)
            for row in rows:
                for cell,v in zip(t.add_row().cells,row):cell.text=str(v)
            md+=['| '+' | '.join(map(str,headers))+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in rows]+['']
        elif typ=='page':story.append(PageBreak());word.add_page_break()
    def footer(c,d):
        w,h=d.pagesize;c.setStrokeColor(colors.HexColor(TEAL));c.line(18*mm,17*mm,w-18*mm,17*mm)
        c.setFont('DV',7);c.setFillColor(colors.HexColor(BLUE));c.drawString(18*mm,12*mm,'LP-R02 · REVISIÓN ACADÉMICA · DATOS DE CAMPO Y PLACAS PENDIENTES');c.drawRightString(w-18*mm,12*mm,str(d.page))
    doc=SimpleDocTemplate(str(path.with_suffix('.pdf')),pagesize=(210*mm,297*mm),leftMargin=18*mm,rightMargin=18*mm,topMargin=17*mm,bottomMargin=23*mm,title=title,author='Proyecto académico · Aquiles Taylor Ramos Yapo')
    doc.build(story,onFirstPage=footer,onLaterPages=footer);word.save(path.with_suffix('.docx'));path.with_suffix('.md').write_text('\n'.join(md)+'\n',encoding='utf-8')

def crear_bloques(P,O,r):
    C=json.loads((P/'datos/lp-r02/parametros.json').read_text());B=json.loads((P/'datos/lp-r02/geometria-base.json').read_text());s=r['resumen'];par=r['parametros_linea']
    f10=next(x for x in r['comparacion_tensiones'] if x['kV']==10 and x['toma_pu']==1);f105=next(x for x in r['comparacion_tensiones'] if x['kV']==10 and x['toma_pu']==1.05)
    f229=next(x for x in r['comparacion_tensiones'] if x['kV']==22.9 and x['toma_pu']==1.05)
    intro=[('h','1. Alcance y decisión de diseño'),('p','Se revisa una sola línea primaria trifásica, sin ramificaciones, entre la transformación de salida de la minicentral de Limbani y una estación de llegada propuesta en Huancasayani. La red de usuarios posterior queda fuera del trazado. Las tres localidades de la demanda representan un ámbito potencial atendido aguas abajo; no tres ramales construidos por este proyecto.'),('p',f'El eje candidato heredado tiene {num(r["longitud_horizontal_m"],3)} m en UTM WGS84 zona19S, {s["apoyos"]} apoyos y {s["vanos"]} vanos. La longitud física EDS por fase es {num(r["longitud_electrica_m"],3)} m. Las coordenadas y cotas DEM proceden de LP-R01: no son levantamiento de campo. Se conservan para auditar el corredor; cada observación impide promoverlo a plano de construcción.'),('p','El manifiesto original fija sistema aislado alimentado por MCH. No se ha encontrado placa que confirme la tensión de salida ni potencia neta de estiaje. La referencia200kW del proyecto de línea y el documento local de otra asignatura150kW requieren conciliación. Se estudian ambos niveles de oferta, sin trasladar una potencia a la otra asignatura.'),('table',['Dato','Estado vigente'],[['Tensión confirmada de salida','Pendiente: placa, relación de T1 y regulación AVR'],['Potencia neta de estiaje','Pendiente: recurso, máquina, auxiliares y reserva para Limbani'],['Demanda de estudio',f'{num(r["demanda_kW"],3)} kW; viviendas proyectadas y cargas supuestas'],['Trazado y predios','Corredor de gabinete; dos SE propuestas, sin predios aprobados'],['Decisión de tensión','Pendiente. Comparar10kV y22.9kV;20/22kV sólo sensibilidad']]),('h','2. Resultado de la evaluación'),('p',f'La revisión sustituye la tracción compartida por cantón por estados independientes de cada vano para la hipótesis de aisladores rígidos. Se hallan {s["apoyos_exceden_flexion_base"]} apoyos que exceden la comprobación de flexión tipo al recalcular el esquema anterior y {s["apoyos_carga_ascendente"]} apoyos con alguna carga ascendente de conductores. Se proponen {s["apoyos_refuerzo_propuesto"]} cambios funcionales a retención para estudiar. Las retenidas ideales totales pasan de {s["retenidas_r01"]} a {s["retenidas_propuestas"]}; su terreno y anclaje siguen sin verificar.'),('p',f'El nuevo cálculo arroja {s["vanos_alerta_galibo"]} vanos con separación inferior al margen académico7.5m respecto al perfil heredado. Separación mínima de esa comparación: {num(s["separacion_perfil_min_m"],3)}m. Esta cifra no demuestra gálibo real ni seguridad de ningún vano, incluso cuando supera7.5m.'),('p',f'Con10kV nominales equivalentes en origen de generación y sin elevación supuesta, la BT de llegada es {num(f10["BT_llegada_V"],1)}V. Con elevación efectiva1.05pu resulta {num(f105["BT_llegada_V"],1)}V. El efecto de los transformadores se debe revisar antes de atribuir toda la caída a la línea.'),('page',)]
    demand=[('h','3. Demanda, horizonte y suficiencia de generación'),('p','Se proyectan viviendas base de2017 al año de estudio2026 usando1% anual. Usuarios potenciales = ceil(viviendas×1.01^(2026−2017)). Las categoríasI/I/II, simultaneidad0.80,60 luminarias y14kW de servicios son hipótesis sin padrón. El resultado no acredita nuevas conexiones ni su distribución secundaria.'),('table',['Localidad','Viviendas2017','Usuarios potenciales','kW'],[[d['localidad'],d['viviendas_base'],d['usuarios_potenciales'],num(d['demanda_kW'],3)] for d in r['demanda']]),('p',f'P_doméstica =154.240kW; P_AP=60×0.0541=3.246kW; P_servicios=14kW. P_total={num(r["demanda_kW"],3)}kW. Con FP0.90: Q=P×tan(acos0.9)=83.054kvar; S=P/0.9=190.540kVA. La carga se concentra en T2 para calcular el transporte, sin inventar ramales de usuario.'),('table',['Oferta','Reserva Limbani','Necesidad10kV','Margen'],[[f'{x["oferta_hipotetica_kW"]} kW',f'{x["reserva_limbani_kW"]} kW',num(x['necesidad_kW']),num(x['margen_kW'])] for x in r['balance_fuente'] if x['kV']==10]),('p','La oferta debe contrastarse con la curva de disponibilidad y con la carga horaria simultánea de ambas localidades. Elevar tensión reduce pérdidas; no compensa un déficit de potencia activa de la central. La proyección a10/20años se exporta con cargas, potencia de generación y kVA para verificar también la capacidad aparente a la altitud del emplazamiento.'),('page',)]
    electric=[('h','4. Memoria de cálculo eléctrico explícita'),('sub','4.1 Datos, resistencia y reactancia'),('p',f'Conductor propuesto AAAC6201-T81,50mm² nominales,49.5mm² efectivos, diámetro9mm, masa135kg/km, R20=0.671ohm/km. Masa y diámetro concuerdan con la tabla de referencia DGE; resistencia, RTS14.7kN, E62GPa y curva de fluencia siguen como datos tipo sin fabricante contratado.'),('p',f'R75 = R20×[1+αR×(75−20)]×Lc/1000 =0.671×(1+0.0036×55)×{num(r["longitud_electrica_m"]/1000,6)} = {num(par["R_ohm_fase"],6)}ohm/fase. Se usa longitud física de conductor; R01 usaba proyección horizontal y subestimaba ligeramente R.'),('p',f'DMG=(Dab×Dbc×Dca)^(1/3)=(1.2×1.2×2.4)^(1/3)={num(par["DMG_m"],6)}m. GMR≈0.7788×d/2={num(par["GMR_m"],7)}m, aproximación a sustituir por GMR de cable trenzado. X=2πf×2×10^-4×ln(DMG/GMR)×Lc(km)={num(par["X_ohm_fase"],6)}ohm/fase, a60Hz.'),('sub','4.2 Qué significa que la salida sea10kV'),('p','Primera frontera: si se fijan exactamente10kV entre fases en el extremo MT de salida, se calcula sólo línea y carga. Segunda frontera: si se fijan380V nominales en la barra equivalente del generador, T1 y T2 agregan sus propias impedancias y pérdidas; la MT inicial ya no es exactamente10kV. Ambas fronteras se tabulan por separado para evitar respuestas incompatibles.'),('table',['MT salida fija kV','MT llegada kV','Corriente A','Pérdida kW'],[[x['tension_origen_kV'],num(x['tension_llegada_kV'],4),num(x['I_A'],3),num(x['perdida_kW'],4)] for x in r['linea_con_origen_MT_fijo']]),('sub','4.3 Flujo con ambos transformadores'),('p','Base250kVA. rTX=Pcu/Sn=3.1/250=0.0124pu; xTX=sqrt(0.06²−0.0124²)=0.058705pu. Zbase=Vnom²/Sbase; ZTX=(r+jx)×Zbase. P0=0.45kW y Q0=2.5kvar por TX son supuestos constantes. Los equipos alternativos se comparan con las mismas pérdidas pu; ofertas reales pueden cambiar el resultado.'),('p','Barrido por fase: i_carga=conj[S_trifásica/(3v)]; corriente de rama=suma de cargas aguas abajo; v_receptor=v_emisor−Z×i; iterar hasta residuo<10^-8V. P_Joule=3|i|²R; Q_serie=3|i|²X. Comprobar P_fuente=P_carga+P0_T1+P0_T2+ΣP_Joule y Q equivalente. Añadir5kW de auxiliares sólo al balance de generación; su FP se supone1.'),('table',['kV nominal','Fuente pu','MT salida/llegada kV','BT V','P línea kW','P generación kW'],[[x['kV'],x['toma_pu'],num(x['MT_salida_kV'],3)+' / '+num(x['MT_llegada_kV'],3),num(x['BT_llegada_V'],1),num(x['perdida_linea_kW'],3),num(x['P_generacion_kW'],2)] for x in r['comparacion_tensiones']]),('p','La elevación efectiva1.025/1.05pu es una sensibilidad del modelo ideal; no ordena cambiar un tap. Comprobar relación real, sentido del selector, impedancias por toma, máximo en vacío, rango AVR y garantía a la altitud. Debe evaluarse carga mínima y máxima y toda la red posterior. El objetivo±5% de estudio no constituye certificación de calidad en medidores.'),('sub','4.4 Comparación económica y necesidad de regulación'),('p',f'A1.05pu,10kV pierde {num(f105["perdida_linea_kW"],3)}kW en línea y22.9kV pierde {num(f229["perdida_linea_kW"],3)}kW: ahorro de pico {num(f105["perdida_linea_kW"]-f229["perdida_linea_kW"],3)}kW. La mejora de BT también depende de T1/T2. No aparece justificación de un elevador intermedio sólo por6.7km: primero resolver tensión nominal, transformadores, AVR y perfil de carga. La inversión adicional no puede decidirse por menor pérdida sin precio de equipos y energía.'),('p','Energía anual de pérdidas =Σ(P_perdida_i×horas_i), con8760horas repartidas25/50/75/100% del pico. Esta curva es sintética. La hoja energia.csv conserva cada bloque. Recuperación simple de sobrecosto: ΔCAPEX/(ΔE_kWh×costo_energía−ΔOPEX); faltan cotizaciones y curva horaria para dar un plazo válido.'),('sub','4.5 Cortocircuito, protección y puesta a tierra'),('p','Ik3≈VLL/[sqrt(3)|Zg+ZT1+Zlínea|]; se distinguen Xd″0.20pu, Xd′0.30pu y Xd1.80pu de estudio. La corriente de falla sostenida puede ser menor que la corriente de carga: no basta elegir fusible o50/51 copiando un proyecto SEIN. Requiere curva de decremento/AVR, arranque de motores, inrush, TC/TT, lógica51V u otra protección y coordinación real. El CSV no es ajuste de relés.'),('p','Si se mantiene MT delta en ambos TX, no hay neutro MT accesible; NGR exige transformador de puesta a tierra. Para5A: RN=VLL/(sqrt3×5); a10kV=1154.7ohm y22.9kV=2644.3ohm. Energía nominal10s=Vfase×5×10; dimensionar equipos y verificar régimen, capacitancias y protección. No sumar un NGR simbólico sin definir el neutro.'),('p','La resistencia de tierra, tensiones de paso/contacto y cimentaciones quedan pendientes. Se requieren Wenner, corriente/tiempo de falla y modelo del terreno. La ampacidad del conductor requiere datos de proveedor y balance térmico a la altitud. Una corrida con h supuesto o el bajo valor de corriente no acredita por sí sola capacidad garantizada.'),('page',)]
    mechanical=[('h','5. Memoria de cálculo mecánico explícita'),('sub','5.1 Un poste13m: qué puede soportar'),('p','Longitud total13m, empotramiento de estudio1.9m, longitud libre11.1m y amarre10.6m. Para13/400,400daN=4000N≈407.9kgf de carga transversal equivalente; no400kg de peso colgado. Con aplicación a0.15m bajo cima, brazo=13−1.9−0.15=10.95m. El punto de ensayo y el empotramiento deben confirmarse con proveedor.'),('p','Momento de trabajo tipo4000×10.95=43.80kN·m. Si la rotura garantizada fuese2×trabajo: Mrot=87.60kN·m. Método de estudio gradoB,phi0.65: resistencia de comparación56.94kN·m. Para600daN,85.41kN·m. Se comparan cargas factorizadas con resistencia reducida; no se aplica además otro divisor2 a esta misma verificación. Peso propio, interacción axial-flexión, fisuración, anclajes y suelo aún requieren comprobación.'),('sub','5.2 Peso, tracción y ángulo son cargas distintas'),('p','Peso lineal por fase=0.135×9.80665=1.323898N/m. En dos vanos iguales85m y terreno horizontal, un apoyo interior recibe aproximadamente el peso de85m por fase:3×0.135×85=34.425kg de cable sin hielo. Eso no incluye aisladores ni poste. La tracción EDS por fase es0.15×14700=2205N; en un terminal, tres fases ejercen6615N horizontales antes de factores. En un ángulo30°, resultante ideal3×2×2205×sin15°=3424.2N. Por eso dividir400 entre kg/m no determina el vano.'),('sub','5.3 Catenaria y cambio de estado'),('p','Se resuelve cada vano por separado bajo la hipótesis de aisladores rígidos. Para apoyo inclinado y viento, se rota al plano de carga. a=H/q; dy=Δz×qv/q; dx=sqrt(L²+Δz²−dy²); x0=dx/2−a×asinh[dy/(2a×sinh(dx/2a))]. y(x)=a[cosh((x−x0)/a)−cosh(x0/a)]. La longitud y las fuerzas tangenciales se calculan con hiperbólicas, sin asumir parábola para desniveles grandes.'),('p','Compatibilidad termoelástica: Lnatural≈Lc−∫Tds/(EA). En el nuevo estado Lnatural_2=Lnatural_ref×[1+αΔT+ε_creep]. Se obtiene H por bisección y se exporta el residuo. Se conserva la sensibilidad heredada345microstrain; la alternativa normativa histórica de temperatura equivalente10°C corresponde230microstrain con α23×10^-6/K y debe contrastarse con curva de proveedor. No se suma simultáneamente10°C y345microstrain.'),('table',['Estado','T°C','V m/s','Hielo mm','Fluencia m/m'],[[x['id'],x['temperatura_c'],x['viento_ms'],x['hielo_mm'],x['creep']] for x in C['clima']]),('sub','5.4 Fuerzas con signo, viento y retenidas'),('p','Las fuerzas de extremo se convierten de cada vano a Este/Norte/Vertical y se suman en el poste. La parte paralela a la cuerda recibe factor1.65; la reacción distribuida horizontal2.5 y vertical1.5. Se muestrea viento0–345° cada15°. No es búsqueda continua exacta del azimut crítico. Se integra el viento sobre un poste cónico tipo180/375mm; dimensiones de15/17m son sensibilidad geométrica, no catálogo certificado.'),('p','Fvertical negativa en la convención del CSV es carga ascendente de los conductores/aisladores. No se reemplaza el desnivel por su valor absoluto. Retenida ideal por ramal: neutraliza el componente horizontal de tracción a45°, Tg=Fh/cos45°; agrega Fh×tan45° hacia abajo. Resistencia mínima rotura≥Tg/0.90 yse conserva el mínimo60kN de laespecificación inicial. El modelo ideal no incluye pretensión, rigidez, deslizamiento ni transferencia real de carga: no demuestra estabilidad ni capacidad de anclaje.'),('p',f'Comparación del esquema de apoyos: {s["apoyos_exceden_flexion_base"]} excedencias de flexión tipo en la base recalculada; {s["apoyos_refuerzo_propuesto"]} apoyos con retención adicional propuesta. Después de esas retenidas ideales quedan {s["apoyos_exceden_flexion_propuesta"]} excedencias de flexión de estudio. Todos mantienen la capacidad axial y de cimentación pendiente; pasar una relación D/C no equivale a aprobación.'),('p',f'El cruce de los160anclajes ideales y sus segmentos con casas/cauces heredados identifica{r["resumen"].get("retenidas_alerta_cartografica",0)} alertas cartográficas. Sus posiciones deben replantearse yrecalcularse antes de aceptar el sistema de retenidas. La ausencia de alerta tampoco demuestra disponibilidad del predio.'),('sub','5.5 Vano admisible: ejemplo controlado'),('table',['Poste tipo','Último vano que pasa m','Primero que falla m','Restricción'],[[x['poste'],x['vano_limite_ejemplo_m'],x['primer_vano_que_falla_m'],x['restriccion']] for x in r['vanos_limite_ejemplo']]),('p','La tabla anterior corresponde sólo a dos vanos iguales en terreno plano, amarre10.6m, hipótesis de cable50mm² y estados indicados. Se recorre10–300m y se exige flexión tipo, separación7.5m de estudio y T/RTS≤40% de estudio. No se transfiere ese vano límite a quebradas, giros, cruces ni terrenos inclinados. En el corredor real cada vano conserva su resultado individual y su observación.'),('sub','5.6 Cálculo desarrollado de un vano'),]
    v=max(r['vanos'],key=lambda v:abs(v['desnivel_m'])/v['longitud_m']);p=next(x for x in r['postes'] if x['id']==v['desde'])
    mechanical +=[('p',f'Ejemplo {v["id"]}, {v["desde"]}–{v["hasta"]}: L={num(v["longitud_m"],4)}m; desnivel de amarres={num(v["desnivel_m"],4)}m. H inicial2205N. EA=62×10^9×49.5×10^-6=3069000N. La pendiente relativa|Δz|/L={num(abs(v["desnivel_m"])/v["longitud_m"],4)} exige conservar la inclinación. Cada fila siguiente procede de una solución independiente del cambio de estado.'),('table',['Estado','H N','T mayor N','Flecha m','Separación modelo m'],[[x['estado'],num(x['H_N'],1),num(max(x['T_izq_N'],x['T_der_N']),1),num(x['flecha_vertical_m'],3),num(x['separacion_perfil_heredado_m'],3)] for x in v['estados'].values()]),('sub','5.7 Apoyos que requieren más atención')]
    selected=sorted(r['postes'],key=lambda p:p['DC_r01_recalculado'],reverse=True)[:5]
    for p in selected:
        mechanical +=[('p',f'{p["id"]}: poste{p["poste_m"]}m; ángulo{num(p["angulo_deg"],2)}°; M sin retenidas={num(p["M_sin_retenidas_kNm"],3)}kN·m; M con retenidas ideales={num(p["M_con_ideales_kNm"],3)}kN·m; M resistente tipo={num(p["M_capacidad_tipo_kNm"],3)}kN·m. D/C base recalculado={num(p["DC_r01_recalculado"],3)}; D/C propuesta={num(p["DC_propuesta"],3)}. Vertical exterior mínima={num(p["vertical_min_kN"],3)}kN. Acciones: {p["acciones"]}.')]
    mechanical +=[('sub','5.8 Ubicación de postes y perfiles pendientes'),('p','La ubicación definitiva se obtiene sobre topografía del eje y sus fases, con cotas de cruce, obstáculos, techo/vegetación, terreno bajo balanceo, fajas y predios. Se recalcula flecha y fuerzas al mover un apoyo. Las alertas actuales identifican dónde insertar apoyo, elevarlo o replantear tramo; no se inventa una coordenada aprobada para ocultar la falta de topografía. Los girosP003/P035/P057 mayores90° exigen replanteo o armado especial. No se presenta hoja008 como una retención equivalente para CAC.'),('page',)]
    quantities=[('h','6. Metrados vinculados al diseño'),('p',f'Conductor de terna tendida=3×ΣLc_EDS={num(r["conductor"]["tendido_terna_m"],3)}m. Puentes/colas provisionales=3fases×ramales retenidos×2m={num(r["conductor"]["puentes_provision_m"],3)}m. Reserva3% sobre ambos={r["conductor"]["reserva_m"]}m. Compra de estudio redondeada={r["conductor"]["total_compra_estudio_m"]}m. El2m por ramal es una provisión que debe sustituirse por la longitud del detalle de armado, diferenciada de la reserva de suministro.'),('table',['Recurso','Unidad','Cantidad de estudio'],[[x['recurso'],x['unidad'],num(x['cantidad'],3)] for x in r['metrados']]),('p','metrado_detallado.csv conserva ID, recurso, fórmula, poste/vano y estado. Los civiles no reciben volumen cerrado: excavación=πD²h/4 y concreto=excavación−volumen desplazado cuando se defina geometría real. Un bloque1.2m o una malla dibujada no acredita capacidad ni resistividad. Las planillas dejan esas dimensiones vacías.'),('h','7. Materiales, montaje y pruebas'),('p','Postes: solicitar carga transversal de trabajo/rotura, posición del ensayo, dimensiones, peso, capacidad axial, interacciónN-M, comportamiento de fisuración, certificados por lote, orificios y transporte. Conductores: ficha AAAC, R20, masa, diámetro, GMR, RTS, E, α, curva tensión/deformación/fluencia y carga mínima de grapas. Aisladores/crucetas: comprobar cargas con signo, distancias y fijación CAC de cada función.'),('p','Transformadores/celdas: capacidad neta a altitud local, relaciones/tomas, uk, pérdidas, grupo, neutro, aislamiento y ensayos. Montaje: replantear y liberar predios; ejecutar geotecnia/cimentaciones; izar con procedimiento del proveedor; tender por poleas; ajustar tabla de tensado a temperatura medida; comprobar puesta a tierra/protecciones y energizar tras pruebas. La tabla de tensado de esta revisión es orientativa para el modelo, no orden de tendido.'),('h','8. Presupuesto, cronograma y cierre'),('p','Se reemplaza el total aparente cerrado por una plantilla con cantidades trazables y precios sin cotizar. El presupuestoR01 se conserva como antecedente estimado; no se reutiliza como oferta local. Suministro, montaje, transporte, obras civiles y gestión se separan para evitar doble contabilización. Se solicita precio entregado en destino y tratamiento de IGV por oferta. APU, gastos, utilidad y cronograma de rendimiento permanecen editables.'),('p','Secuencia propuesta:1) confirmar curso y fuente;2) verificar generación y demanda;3) comparar tensión con cotizaciones;4) levantar corredor/cruces y predios;5) resolver mecánica/aislamiento/protección/tierra/cimentación;6) congelar planillas;7) generar CAD, metrados y presupuesto;8) revisión de responsable y pruebas. Duraciones en hoja de planificación son hipótesis, sin fecha de obra comprometida.'),('page',)]
    refs=json.loads((P/'datos/lp-r02/fuentes.json').read_text())
    final=[('h','9. Recursos y referencias de contraste'),('p','Se inventariaron los archivos del repositorio y se comprobaron los tresZIP existentes medianteCRC. ElZIP de Capachica se abrió y sus seisDXF se analizaron; aporta organización planta/perfil/unifilar/detalles, no prueba las cargas de Limbani. ElZIPLP-R01 se conserva íntegro; incluye archivos de bloqueoDW L/DWL2 que no se incorporan al paquete nuevo. La bibliotecaDGE es referencia; no constituye adaptación validada aCAC.'),('p','Los términos de Electro Puno consultados utilizan once volúmenes y anexos. Las ocho carpetas aquí responden a organización académica, no a una exigencia universal de ocho capítulos. Se agrupan cálculos eléctricos/mecánicos/protección en03, armados en04 y especificaciones en05, preservando la correspondencia de contenido.'),('p','SEACE: se descargaron dos contratos oficiales comparables,Ubinas33kV yCarhuaz13.2kV, y la ficha de poste13/400. Los contratos no incluyen los planos completos del expediente. Para modelos gráficos se descargaron delSINIA el planos de componentesLircay, mapaTablachaca y planillaChoclococha. El buscadorSEACE redirige a una aplicación dinámica; los documentos directos pudieron recuperarse por descargaHTTP aunque la herramienta web devolvía403.'),('table',['ID y entidad','Documento local / límite'],[[x['id']+' '+x['entidad'],Path(x['archivo']).name+' · '+x['uso_y_limites']] for x in refs]),('p','Cada fuente conserva URL, fecha, SHA-256, tamaño y uso permitido en08-recursos/fuentes.json. Las referencias históricas pueden tener inconsistencias: se observaron diferencias de tensión/totales enTinyacclla y porcentajes del resumen deUbinas; no se trasladan sus cifras como reglas o precios actuales.'),('h','10. Datos necesarios para cerrar ingeniería'),('table',['Prioridad','Dato verificable','Decisión afectada'],[['1','Placas generador/T1/T2, ubicación y predios','Tensión nominal, potencia neta y transformación'],['1','Aforos/curva de disponibilidad y demanda horaria','Suficiencia150/200kW, reserva y horizonte'],['1','Topografía de campo de terna y cruces','Ubicación, altura y distancia real entre postes'],['1','Ficha de poste y armadoCAC, cargasN-M','Soportes, retenidas y accesorios'],['1','Geotecnia y Wenner','Cimentaciones, anclajes y tensiones de paso/contacto'],['1','AVR/decremento, TC/TT y curvas de equipos','Coordinación de protecciones e inrush'],['2','Cotizaciones con logística y ensayos','Elección10/22.9kV y presupuesto'],['2','Consigna/rúbrica y docente de esta asignatura','Formato de entrega y alcance de evaluación']]),('p','La ejecución informática y la revisión documental de esta entrega no equivalen a aprobación profesional ni a levantamiento. No se requiere permiso del usuario para continuar corrigiendo cálculos; sí se requieren datos técnicos reales para cerrar las decisiones dependientes. El archivoCONTINUIDAD_IA.md indica cómo reproducir y qué datos actualizar sin reactivar fuentes históricas.')]
    return intro,demand,electric,mechanical,quantities,final

def estilo_excel(w):
    for s in w:
        s.freeze_panes='A2';s.auto_filter.ref=s.dimensions
        for c in s[1]:c.font=Font(bold=True,color='FFFFFF');c.fill=PatternFill('solid',fgColor='163B55');c.alignment=Alignment(wrap_text=True)
        s.row_dimensions[1].height=32
        for col in s.columns:
            letter=col[0].column_letter;s.column_dimensions[letter].width=min(60,max(14,max(len(str(c.value or '')) for c in list(col)[:100])+2))
        for row in s.iter_rows(min_row=2):
            for c in row:
                c.alignment=Alignment(vertical='top',wrap_text=True)
                if isinstance(c.value,(float,int)):c.number_format='0.000'
                if c.data_type=='f':c.font=Font(color='087F8C')
    w.calculation.fullCalcOnLoad=True

def hojas_csv(w,O,folder,names):
    for name in names:
        with (O/folder/(name+'.csv')).open(encoding='utf-8-sig') as f:
            data=list(csv.reader(f))
        s=w.create_sheet(name[:31])
        for row in data:
            vals=[]
            for x in row:
                try:vals.append(float(x) if '.' in x or 'e-' in x.lower() else int(x))
                except ValueError:vals.append(x or None)
            s.append(vals)

