def documentar(P,O,r,met,civil):
    blocks=crear_bloques(P,O,r);allblocks=[b for chapter in blocks for b in chapter]
    doc_outputs(allblocks,O/'01-expediente/Expediente_revisado_LP_R02','Evaluación y expediente de estudio · Limbani–Huancasayani')
    doc_outputs([*blocks[1],*blocks[2],*blocks[3]],O/'03-calculos/Memoria_calculo_explicita_LP_R02','Memoria de cálculo explícita · LP-R02')
    doc_outputs([*blocks[0],*blocks[-1]],O/'07-evaluacion-y-pendientes/Evaluacion_tecnica_LP_R02','Evaluación técnica y datos pendientes · LP-R02')
    doc_outputs([*blocks[4][3:]],O/'05-especificaciones/Especificaciones_y_montaje_R02','Especificaciones para completar el diseño · LP-R02')
    libros(P,O,r,met,civil)
